/* ============================================================
   HOLA TSOFT — Hoja de estilos principal
   Archivo: css/styles.css
   ============================================================ */

/* ============================================================
   PASO 1 — Variables globales
   ============================================================ */
:root {
  --color-primary:    #0A2463;
  --color-accent:     #3E92CC;
  --color-energy:     #FF6B35;
  --color-white:      #FFFFFF;
  --color-bg:         #F5F7FA;
  --color-text:       #1A1A2E;
  --color-text-muted: #6B7280;
  --color-border:     #D1D5DB;

  --font-family-base: 'Inter', 'Segoe UI', Arial, sans-serif;
  --font-size-base:   1rem;
  --font-size-sm:     0.875rem;
  --font-size-lg:     1.25rem;
  --font-size-xl:     2rem;
  --font-size-hero:   3rem;

  --spacing-xs:  0.25rem;
  --spacing-sm:  0.5rem;
  --spacing-md:  1rem;
  --spacing-lg:  1.5rem;
  --spacing-xl:  2rem;
  --spacing-2xl: 3rem;

  --radius-sm:  4px;
  --radius-md:  8px;
  --radius-lg:  16px;

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.12);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.15);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.20);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
}

/* ============================================================
   PASO 2 — Reset y base global
   ============================================================ */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  color: var(--color-text);
  background-color: var(--color-bg);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  line-height: 1.6;
}

/* ============================================================
   PASO 3 — Header / Navbar
   ============================================================ */
.site-header {
  background-color: var(--color-primary);
  padding: var(--spacing-md) var(--spacing-xl);
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 1;
  box-shadow: var(--shadow-md);
}

.header-brand {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.brand-logo {
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-white);
  letter-spacing: 0.05em;
  user-select: none;
}

.brand-logo span {
  color: var(--color-energy);
}

.brand-tagline {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  letter-spacing: 0.03em;
}

/* ============================================================
   PASO 4 — Contenido principal
   ============================================================ */
.site-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-2xl);
  padding: var(--spacing-2xl) var(--spacing-xl);
  max-width: 960px;
  width: 100%;
  margin: 0 auto;
}

/* ============================================================
   PASO 5 — Sección selector de países
   ============================================================ */
.selector-section {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
}

.selector-title {
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: -0.01em;
}

.selector-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: var(--spacing-md);
}

/* ============================================================
   PASO 6 — Botones de país
   ============================================================ */
.country-btn {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md);
  background-color: var(--color-white);
  color: var(--color-text);
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  font-weight: 500;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color var(--transition-fast),
              box-shadow var(--transition-fast),
              background-color var(--transition-fast),
              color var(--transition-fast);
  user-select: none;
  white-space: nowrap;
}

.country-btn:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
  background-color: var(--color-bg);
}

.country-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.country-btn.is-active {
  border-color: var(--color-primary);
  background-color: var(--color-primary);
  color: var(--color-white);
  box-shadow: var(--shadow-md);
}

/* ============================================================
   PASO 7 — Sección de saludo
   ============================================================ */
.greeting-section {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.greeting-card {
  background-color: var(--color-white);
  border-radius: var(--radius-lg);
  padding: var(--spacing-2xl);
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-lg);
  text-align: center;
  min-height: 220px;
  justify-content: center;
  transition: box-shadow var(--transition-base);
}

.greeting-flag {
  font-size: var(--font-size-hero);
  line-height: 1;
  transition: transform var(--transition-base);
}

.greeting-flag:not(:empty) {
  transform: scale(1.05);
}

.greeting-text {
  font-size: var(--font-size-hero);
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.greeting-sub {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  font-weight: 400;
}

/* ============================================================
   PASO 8 — Estado placeholder (sin país seleccionado)
   ============================================================ */
.greeting-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-sm);
}

.placeholder-text {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  font-weight: 400;
}

/* ============================================================
   PASO 9 — Footer
   ============================================================ */
.site-footer {
  background-color: var(--color-primary);
  padding: var(--spacing-lg) var(--spacing-xl);
  text-align: center;
  margin-top: auto;
}

.footer-copy {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  letter-spacing: 0.02em;
}

/* ============================================================
   PASO 10 — Responsividad
   ============================================================ */
@media (max-width: 600px) {
  .site-header {
    padding: var(--spacing-md);
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-sm);
  }

  .site-main {
    padding: var(--spacing-xl) var(--spacing-md);
    gap: var(--spacing-xl);
  }

  .selector-title {
    font-size: var(--font-size-lg);
  }

  .selector-grid {
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
    gap: var(--spacing-sm);
  }

  .greeting-card {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .greeting-text {
    font-size: var(--font-size-xl);
  }

  .greeting-flag {
    font-size: var(--font-size-xl);
  }
}
